parameters.functionCode:
// Launch coding agent session
const prompt = $json.prompt || 'Implement feature';
const workdir = $json.workdir || '/workspace';
const sessionName = $json.sessionName || 'code-gen-' + Date.now();

return [{ json: {
  action: 'agent_launch',
  prompt: prompt,
  name: sessionName,
  workdir: workdir,
  config: { permission_mode: 'plan', plan_approval: 'delegate', worktree_strategy: 'delegate' }
}}];

// Wait for plan approval
const sessionId = $json.sessionId;
// In practice, this would poll agent_sessions(status='waiting')
return [{ json: { sessionId, waitingFor: 'plan_approval' } }];

// Approve plan and continue
const sessionId = $json.sessionId;
return [{ json: { action: 'agent_respond', session: sessionId, message: 'Approved. Go ahead.', approve: true, approval_rationale: 'Plan matches requirements.' } }];

// Monitor until completion
const sessionId = $json.sessionId;
return [{ json: { sessionId, action: 'monitor' } }];

// Merge worktree if successful
const sessionId = $json.sessionId;
return [{ json: { action: 'agent_merge', session: sessionId, summary: 'Implemented feature from code-gen workflow' } }];
